// Full package checks need the same reviewed 1800-second per-check budget.
// The underlying checker retains all exit, expectation and approval semantics.
import { spawnSync } from "node:child_process";
const tool = "/Users/z3437171/.codex/skills/unlazy/scripts/gate-check.mjs";
const args = process.argv.slice(2);
if (!args.includes("--status") && !args.includes("--timeout")) args.push("--timeout", "1800");
const run = spawnSync(process.execPath, [tool, ...args], { stdio: "inherit", env: process.env });
if (run.error) { console.error(run.error.message); process.exit(2); }
process.exit(run.status ?? 2);
